    customer_email: "billing@acme.com",
    amount: 1500.00,
    due_date: "2024-01-01",
    days_overdue: 3,
    status: "overdue",
    payment_link: "https://pay.example.com/inv-001"
  },
  {
    invoice_id: "INV-002",
    invoice_number: "2024-002",
    customer_id: "CUST-456",
    customer_name: "TechStart Inc",
    customer_email: "accounts@techstart.com",
    amount: 3200.00,
    due_date: "2024-01-05",
    days_overdue: 10,
    status: "overdue",
    payment_link: "https://pay.example.com/inv-002"
  }
];

return sampleInvoices.map(invoice => ({ json: invoice }));

// Get customer consent flags from CRM
// TODO: Replace with real CRM API call (HubSpot, Salesforce, etc.)

const invoice = $input.item.json;

// Sample customer context
const customerContext = {
  customer_id: invoice.customer_id,
  consent_flags: {
    can_email: true,
    can_sms: true,
    can_call: false
  },
  payment_history: {
    total_invoices: 12,
    on_time_payments: 10,
    late_payments: 2
  },
  relationship_status: "good",
  last_reminder_sent_at: null
};

return {
  ...invoice,
  customer_context: customerContext
};

// VALIDATOR: Consent Check Failed
const invoice = $input.item.json;

console.log('❌ BLOCKED: No email consent for customer', invoice.customer_id);

// Log violation
return {
  validation_result: 'FAILED',
  reason: 'no_email_consent',
  invoice_id: invoice.invoice_id,
  customer_id: invoice.customer_id,
  action_taken: 'blocked',
  requires_human_review: true
};

// Determine escalation stage based on days overdue
const invoice = $input.item.json;
const daysOverdue = invoice.days_overdue;

let stage, channel, tone, template;

if (daysOverdue >= 1 && daysOverdue <= 7) {
  stage = '1_friendly_reminder';
  channel = 'email';
  tone = 'friendly';
  template = 'gentle_reminder';
} else if (daysOverdue >= 8 && daysOverdue <= 15) {
  stage = '2_second_notice';
  channel = 'email';
  tone = 'professional';
  template = 'second_notice';
} else if (daysOverdue >= 16 && daysOverdue <= 30) {
  stage = '3_final_notice';
  channel = 'email';
  tone = 'firm';
  template = 'final_notice';
} else if (daysOverdue >= 31) {
  stage = '4_human_escalation';
  channel = 'human_task';
  tone = 'n/a';
  template = 'n/a';
}

return {
  ...invoice,
  escalation: {
    stage,
    channel,
    tone,
    template,
    days_overdue: daysOverdue
  }
};

// Generate personalized reminder message
const invoice = $input.item.json;
const { customer_name, invoice_number, amount, days_overdue, payment_link } = invoice;
const { tone, template } = invoice.escalation;

// Message templates
const templates = {
  gentle_reminder: {
    subject: `Friendly Reminder: Invoice #${invoice_number}`,
    body: `Hi ${customer_name},

I hope this message finds you well! I wanted to send a quick reminder that invoice #${invoice_number} for $${amount} was due ${days_overdue} days ago.

I understand things can get busy, so here's a quick payment link:

${payment_link}

If you've already sent payment, please disregard this message. If you have any questions, feel free to reach out.

Thank you!

Best regards,
Accounts Team`
  },
  second_notice: {
    subject: `Second Notice: Invoice #${invoice_number} - ${days_overdue} Days Overdue`,
    body: `Hi ${customer_name},

I'm following up on invoice #${invoice_number} for $${amount}, which is now ${days_overdue} days past due.

I want to help resolve this quickly:

• Quick payment link: ${payment_link}
• Questions? Reply to this email

If there's an issue preventing payment, please let me know so we can work together on a solution.

Thank you for your attention to this matter.

Best regards,
Accounts Team`
  },
  final_notice: {
    subject: `FINAL NOTICE: Invoice #${invoice_number} - Action Required`,
    body: `${customer_name},

This is a final notice regarding invoice #${invoice_number} for $${amount}, which is now ${days_overdue} days overdue.

We need to resolve this matter promptly. Please take action immediately:

• Pay now: ${payment_link}
• Contact us to arrange payment

If we don't hear from you within 7 days, we may need to take further action.

We value your partnership and hope to resolve this quickly.

Best regards,
Accounts Team`
  }
};

const message = templates[template] || templates.gentle_reminder;

return {
  ...invoice,
  generated_message: {
    subject: message.subject,
    body: message.body,
    tone: tone,
    template: template
  }
};

// Audit log entry
const invoice = $input.item.json;
const timestamp = new Date().toISOString();

const auditEntry = {
  event_type: 'reminder_sent',
  timestamp: timestamp,
  invoice_id: invoice.invoice_id,
  customer_id: invoice.customer_id,
  amount: invoice.amount,
  days_overdue: invoice.days_overdue,
  escalation_stage: invoice.escalation?.stage,
  channel: invoice.escalation?.channel || 'email',
  message_subject: invoice.generated_message?.subject,
  status: 'success'
};

console.log('✅ Reminder sent:', auditEntry);

return auditEntry;

// Create human task for high-value invoice
const invoice = $input.item.json;

const task = {
  priority: 'high',
  title: `High-Value Invoice Needs Review: ${invoice.invoice_number}`,
  description: `Invoice: ${invoice.invoice_number}\nCustomer: ${invoice.customer_name}\nAmount: $${invoice.amount}\nDays Overdue: ${invoice.days_overdue}\n\nThis invoice exceeds the auto-send threshold ($10,000).\nPlease review and take appropriate action.`,
  invoice_id: invoice.invoice_id,
  customer_id: invoice.customer_id,
  amount: invoice.amount,
  action_required: 'manual_review'
};

console.log('⚠️ High-value invoice flagged for human review:', task);

return task;

// Create human escalation task
const invoice = $input.item.json;

const task = {
  priority: 'urgent',
  title: `Invoice Requires Human Attention: ${invoice.invoice_number}`,
  description: `Invoice: ${invoice.invoice_number}\nCustomer: ${invoice.customer_name}\nAmount: $${invoice.amount}\nDays Overdue: ${invoice.days_overdue}\nStage: ${invoice.escalation?.stage}\n\nThis invoice has reached escalation stage requiring human intervention.`,
  invoice_id: invoice.invoice_id,
  customer_id: invoice.customer_id,
  amount: invoice.amount,
  days_overdue: invoice.days_overdue,
  action_required: 'manual_escalation'
};

console.log('🚨 Invoice escalated to human:', task);

return task;
